def summarize(records: list[dict]) -> list[dict]:
    """Sum units by exact SKU, treating null units as zero."""
    totals = {}
    for record in records:
        sku = record["sku"]
        units = record["units"]
        totals[sku] = totals.get(sku, 0) + (0 if units is None else units)
    return [{"sku": sku, "units": int(totals[sku])} for sku in sorted(totals)]

