def parse_records(text: str) -> list[dict]:
    def reject_constant(value):
        raise ValueError("Invalid JSON constant: " + value)

    def unique_object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("Duplicate object key: " + key)
            result[key] = value
        return result

    records = []
    seen_ids = set()
    for line_number, line in enumerate(text.split("\n"), 1):
        if not line.strip():
            continue
        try:
            record = json.loads(
                line,
                object_pairs_hook=unique_object,
                parse_constant=reject_constant,
            )
        except (ValueError, RecursionError) as error:
            raise ValueError("Invalid JSON on line " + str(line_number)) from error
        if not isinstance(record, dict) or set(record) != {"id", "value"}:
            raise ValueError("Each record must contain exactly id and value")
        record_id = record["id"]
        if not isinstance(record_id, str) or not record_id.strip():
            raise ValueError("id must be a non-whitespace string")
        value = record["value"]
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an integer, not a boolean")
        if record_id in seen_ids:
            raise ValueError("Duplicate id: " + record_id)
        seen_ids.add(record_id)
        records.append(record)
    return records

