def parse_records(text: str) -> list[dict]:
    def object_from_pairs(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise ValueError("Duplicate object key")
            obj[key] = value
        return obj

    def reject_constant(value):
        raise ValueError("Invalid JSON constant")

    records = []
    seen_ids = set()
    for line_number, line in enumerate(text.split("\n"), 1):
        if not line.strip():
            continue
        try:
            record = json.loads(
                line,
                object_pairs_hook=object_from_pairs,
                parse_constant=reject_constant,
            )
        except (ValueError, RecursionError) as error:
            raise ValueError("Invalid JSON on line " + str(line_number)) from error
        if not isinstance(record, dict) or set(record) != {"id", "value"}:
            raise ValueError("Each record must have exactly id and value")
        identifier = record["id"]
        if not isinstance(identifier, str) or not identifier.strip():
            raise ValueError("id must be a non-whitespace string")
        if not isinstance(record["value"], int) or isinstance(record["value"], bool):
            raise ValueError("value must be an integer, not boolean")
        if identifier in seen_ids:
            raise ValueError("Duplicate id")
        seen_ids.add(identifier)
        records.append(record)
    return records
